import type { Project } from '../../../src'
import { path } from '@servicenow/sdk-build-core'
import { XMLParser } from 'fast-xml-parser'
import { gunzipSync } from 'zlib'
import * as fs from 'fs'

export { createTestContext } from '../../test-utils'

/**
 * Merge an array of "record_update" objects into one combined object.
 * – For every table name (sys_hub_flow, sys_hub_action_instance_v2, …)
 *   we always store an array.
 * – If the source already has an array we concatenate,
 *   otherwise we push the single record.
 * @param updates - Array of record update objects to merge
 * @param filterDeleteMultiple - If true, filters out entries with action="delete_multiple" (default: false)
 */
export function mergeRecordUpdates(
    updates: Record<string, any>[],
    filterDeleteMultiple: boolean = false
): Record<string, any[]> {
    const merged: Record<string, any[]> = {}

    for (const rec of updates) {
        Object.entries(rec).forEach(([table, value]) => {
            if (!merged[table]) {
                merged[table] = []
            }

            if (Array.isArray(value)) {
                const items = filterDeleteMultiple
                    ? value.filter((item) => item?.['@_action'] !== 'delete_multiple')
                    : value
                merged[table].push(...items)
            } else if (value && typeof value === 'object') {
                if (!filterDeleteMultiple || value['@_action'] !== 'delete_multiple') {
                    merged[table].push(value)
                }
            }
        })
    }
    return merged
}

export const getCv = (v: any) => v?.$cv?.$v

export async function getMergedRecordUpdates(
    project: Project,
    fileName: string,
    directory: string = 'create',
    filterDeleteMultiple: boolean = true
) {
    const fileContent = loadTestFile(fileName, directory)
    project.addFile({ path: fileName, content: fileContent })
    const output = await project.getFile(fileName)!.getOutput()
    const parser = new XMLParser({ ignoreAttributes: false })
    return mergeRecordUpdates(
        output.map((f) => parser.parse(f.content)['record_update']),
        filterDeleteMultiple
    )
}

export function unzipInputArray(base64: string) {
    return JSON.parse(gunzipSync(Buffer.from(base64, 'base64')).toString()) as any[]
}

export function findInput(inputs: any[], name: string) {
    return inputs.find((i) => i.name === name)
}

// Helper function to load test file content
export function loadTestFile(fileName: string, directory: string = 'create'): string {
    return fs.readFileSync(path.resolve(__dirname, directory, fileName), 'utf-8')
}

/**
 * Validates that an action in the generated code only contains expected fields
 * and no extra/incorrect fields.
 *
 * @param content - The generated TypeScript code content
 * @param actionName - The name of the action to validate (e.g., 'addWorknoteLinkToContext')
 * @param expectedFields - Array of field names that should be present
 * @param context - Test context with expect function
 */
export function validateNoExtraFields(
    content: string,
    actionName: string,
    expectedFields: string[],
    context: { expect: any }
): void {
    const { expect } = context

    // Find the action call in the content
    // Action structure: wfa.action(action.core.name, { metadata }, { inputs })
    // We need to capture the THIRD {} block (inputs), not the first (metadata)
    // Pattern: action.core.actionName, skip first {}, skip second {}, capture third {}
    const actionRegex = new RegExp(
        `action\\.core\\.${actionName}[\\s\\S]*?` + // Find action.core.actionName
            `\\{[\\s\\S]*?\\}[\\s\\S]*?` + // Skip first {} (metadata)
            `\\{([\\s\\S]*?)\\}`, // Capture second {} (inputs)
        'm'
    )
    const match = content.match(actionRegex)

    if (!match) {
        // If action not found, skip validation (may be in a different format)
        return
    }

    const actionBody = match[1]

    // Extract field names from the action body
    // Matches patterns like: field_name: value,
    const fieldRegex = /(\w+)\s*:/g
    const foundFields: string[] = []
    let fieldMatch: RegExpExecArray | null

    while ((fieldMatch = fieldRegex.exec(actionBody)) !== null) {
        const fieldName = fieldMatch[1]
        // Skip special fields like $id, $cv, etc.
        if (!fieldName.startsWith('$')) {
            foundFields.push(fieldName)
        }
    }

    // Check for unexpected fields
    const unexpectedFields = foundFields.filter((field) => !expectedFields.includes(field))

    if (unexpectedFields.length > 0) {
        expect(unexpectedFields).toEqual([])
        // This will fail the test with a clear message showing which fields are unexpected
    }
}
